const emptyData = () => ({
  products: [], quotes: [], salesOrders: [], purchaseOrders: [], transfers: [], expenses: [], returns: [], payments: [], repacks: [], loanReturns: [], stocktakes: [],
  counters: { quote: 1, sales: 1, purchase: 1, transfer: 1, exp: 1, ret: 1, product: 1, pay: 1, repack: 1, loanReturn: 1 },
  invoiceSettings: { shopName: "", tagline: "", phone: "", footerNote: "", logoDataUrl: "" },
});

const mergeWithDefaults = (stored) => {
  const base = emptyData();
  return {
    ...base,
    ...stored,
    counters: { ...base.counters, ...(stored.counters || {}) },
    invoiceSettings: { ...base.invoiceSettings, ...(stored.invoiceSettings || {}) },
  };
};

const canAccess = (user, moduleId) => !!user && (user.isAdmin || (user.permissions && user.permissions[moduleId]));

const canAccessRegister = (user, moduleId, registerId) => {
  if (!user) return false;
  if (user.isAdmin) return true;
  if (!canAccess(user, moduleId)) return false;
  const regPerms = user.registerPermissions && user.registerPermissions[moduleId];
  if (regPerms === undefined) return true; // not configured yet -> full access within the module
  return !!regPerms[registerId];
};

// Editing/deleting products in Stock Levels (and Import Excel) is gated
// separately from merely viewing Stock — only admins, or a user an admin
// has explicitly granted stockEditRights to, can change the product list.
const canEditStock = (user) => !!user && (user.isAdmin || !!user.stockEditRights);

const accessibleLocations = (user, locations) => {
  if (!user) return [];
  if (user.isAdmin) return locations;
  return locations.filter((l) => user.locationIds && user.locationIds.includes(l.id));
};

/* ---------------------------------------------------------
   Firestore data layer
--------------------------------------------------------- */
const LOCATIONS_DOC = doc(db, "meta", "locations");
const USERS_COL = collection(db, "users");
const locationDocRef = (locationId) => doc(db, "business", locationId);

async function ensureLocationsList() {
  const snap = await getDoc(LOCATIONS_DOC);
  if (!snap.exists()) await setDoc(LOCATIONS_DOC, { list: [{ id: "main", name: "Main Shop" }] });
}
async function ensureLocationDoc(locationId) {
  const snap = await getDoc(locationDocRef(locationId));
  if (!snap.exists()) await setDoc(locationDocRef(locationId), emptyData());
}
async function saveLocationData(locationId, changes) {
  // Only ever writes the specific top-level fields passed in `changes` —
  // never the whole document. This is deliberate: a full-document setDoc
  // sends this device's entire local copy (products, sales, everything)
  // on every save, so if that copy was even slightly out of date (another
  // device had just written something), it would silently overwrite
  // perfectly good data this device didn't even touch. updateDoc only
  // changes the named fields, leaving everything else exactly as the
  // server already has it.
  // No try/catch here on purpose — a failed write must propagate so the
  // caller can warn the person and offer a retry, instead of silently
  // pretending the save worked.
  await updateDoc(locationDocRef(locationId), changes);
}

// Race-safe save for anything that appends to or edits a shared list —
// sales orders, stock levels, payments, purchase orders, transfers,
// repacks, returns, loan returns, stocktakes, quotes, expenses, counters.
// A plain updateDoc (above) is only safe when the caller already knows the
// exact final value of every field it's touching. But an "append a new
// order to the list" or "deduct stock for this sale" save is normally
// built from this device's own local copy of the data — and if another
// device (or another tab, or a flaky connection on this same device)
// writes to one of those SAME fields a moment earlier, this device's save
// still goes out built from the OLD copy, silently overwriting the other
// write. That is how a sales order can appear to save successfully and
// then vanish, while the stock it deducted stays deducted — the new
// order never had a chance to be included in the stale array this write
// sent back to the server.
// This function closes that gap: it reads the location's document fresh
// from the server at the moment of the write, lets the caller compute the
// new field values against THAT fresh copy (not local state), and commits
// everything in one atomic transaction. If another write lands in the
// (usually tiny) window between the read and the commit, Firestore
// automatically re-runs the whole transaction against the newer data —
// so two near-simultaneous saves merge instead of one quietly erasing
// the other.
async function saveLocationDataTransactional(locationId, computeChanges) {
  const ref = locationDocRef(locationId);
  return runTransaction(db, async (tx) => {
    const snap = await tx.get(ref);
    const fresh = mergeWithDefaults(snap.exists() ? snap.data() : {});
    const changes = computeChanges(fresh);
    tx.update(ref, changes);
    return { fresh, changes };
  });
}

async function saveLocationsList(list) {
  try { await setDoc(LOCATIONS_DOC, { list }); } catch (e) { console.error("Save failed", e); }
}

/* ---------------------------------------------------------
   Daily backups — a full snapshot of this location's data,
   written to its own safe corner of the database every day,
   separate from the live data. If the live data is ever damaged,
   any recent day's snapshot can be restored from Settings.
--------------------------------------------------------- */
const backupsColRef = (locationId) => collection(db, "business", locationId, "backups");

async function createBackupSnapshot(locationId, data) {
  const dateId = todayISO();
  const snapshot = { ...data, backedUpAt: new Date().toISOString() };
  await setDoc(doc(backupsColRef(locationId), dateId), snapshot);
}

async function listBackups(locationId, max = 30) {
  const q = query(backupsColRef(locationId), orderBy("backedUpAt", "desc"), limit(max));
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...d.data() }));
}

async function restoreFromBackup(locationId, backup) {
  // A restore is a full replacement of the live document, by design —
  // unlike normal everyday saves, this one genuinely means "make the live
  // data exactly match this snapshot," so a full setDoc is correct here.
  const { id, backedUpAt, ...rest } = backup;
  await setDoc(locationDocRef(locationId), { ...emptyData(), ...rest });
}

/* ---------------------------------------------------------
   Image resize for logo upload (kept small so Firestore docs stay light)
--------------------------------------------------------- */
function resizeImageFile(file, maxWidth = 260) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const scale = Math.min(1, maxWidth / img.width);
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", 0.75));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

