/* ---------------------------------------------------------
   Product picker — search, select, and it locks in (no more
   dropdown once chosen; delete the line to fix a mistake)
--------------------------------------------------------- */
function ProductPicker({ products, value, onChange }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const selected = products.find((p) => p.id === value);

  if (selected) {
    return (
      <div className="flex items-center justify-between gap-2">
        <div>
          <div className="font-medium text-sm">{selected.name}</div>
          <div className="text-[11px] text-slate-400 font-mono">{selected.sku} · In stock: {selected.stock}</div>
        </div>
        <button type="button" onClick={() => onChange("")} className="text-[11px] text-slate-400 hover:text-red-600 flex-shrink-0">Change</button>
      </div>
    );
  }

  const filtered = query.trim() === "" ? products.slice(0, 50) :
    products.filter((p) => (p.name + " " + p.sku + " " + p.category).toLowerCase().includes(query.toLowerCase())).slice(0, 50);

  return (
    <div className="relative">
      <div className="relative">
        <Search size={13} className="absolute left-2 top-2.5 text-slate-400" />
        <input
          className={inputCls + " pl-7"}
          placeholder="Search product…"
          value={query}
          onChange={(e) => { setQuery(e.target.value); setOpen(true); }}
          onFocus={() => setOpen(true)}
          onBlur={() => setTimeout(() => setOpen(false), 150)}
        />
      </div>
      {open && (
        <div className="absolute z-20 mt-1 w-full max-h-56 overflow-y-auto bg-white border border-slate-200 rounded-md shadow-lg">
          {filtered.length === 0 && <div className="px-3 py-2 text-sm text-slate-400">No matches</div>}
          {filtered.map((p) => (
            <button key={p.id} type="button"
              onMouseDown={(e) => { e.preventDefault(); onChange(p.id); setOpen(false); setQuery(""); }}
              className="w-full text-left px-3 py-2 text-sm hover:bg-slate-50 flex justify-between items-center gap-2">
              <span className="truncate">{p.name} {p.sku ? `(${p.sku})` : ""}</span>
              <span className="text-slate-400 font-mono text-xs flex-shrink-0">stock: {p.stock}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

