/* ---------------------------------------------------------
   Line item editor
--------------------------------------------------------- */
function LineItemsEditor({ items, setItems, products, priceField, showCost }) {
  const addLine = () => setItems([...items, { id: uid(), productId: "", qty: 1, price: 0 }]);
  const removeLine = (id) => setItems(items.filter((l) => l.id !== id));
  const updateLine = (id, patch) => setItems(items.map((l) => (l.id === id ? { ...l, ...patch } : l)));
  const onProductChange = (id, productId) => {
    const p = products.find((p) => p.id === productId);
    updateLine(id, { productId, price: p ? p[priceField] : 0 });
  };
  return (
    <div className="space-y-3">
      {items.map((line) => (
        <div key={line.id} className="border border-slate-200 rounded-md p-3 bg-white">
          <div className="flex items-start justify-between gap-2 mb-3">
            <div className="flex-1"><ProductPicker products={products} value={line.productId} onChange={(productId) => onProductChange(line.id, productId)} /></div>
            <button type="button" onClick={() => removeLine(line.id)} className="text-slate-400 hover:text-red-600 mt-0.5 flex-shrink-0" aria-label="Remove line"><Trash2 size={16} /></button>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <Field label="Qty">
              <input type="number" inputMode="numeric" min="0" className={inputCls + " text-base"} value={line.qty}
                onChange={(e) => updateLine(line.id, { qty: Number(e.target.value) })} />
            </Field>
            <Field label={showCost ? "Unit Cost" : "Unit Price"}>
              <input type="number" inputMode="decimal" min="0" step="0.01" className={inputCls + " text-base"} value={line.price}
                onChange={(e) => updateLine(line.id, { price: Number(e.target.value) })} />
            </Field>
            <Field label="Line Total">
              <div className={inputCls + " bg-slate-50 text-right font-mono flex items-center justify-end"}>{money(line.qty * line.price)}</div>
            </Field>
          </div>
        </div>
      ))}
      {items.length === 0 && (
        <div className="text-center text-slate-400 text-sm py-6 border border-dashed border-slate-200 rounded-md">No items yet. Add a line below.</div>
      )}
      <Btn variant="ghost" onClick={addLine}><Plus size={14} /> Add line</Btn>
    </div>
  );
}

